/*
 * A219608  Odd terms in A060142.
 * https://oeis.org/A219608
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = 2*S(n-1) + 1, where S(0)=0, S(1)=1, ... is the sorted set
 *            A060142 (0 in S; x in S => 2x+1, 4x in S); generated by a
 *            min-heap
 * Range:     u8 n <= 22, u16 n <= 996, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 72 terms through n = 9345 (2026-11-07)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>
#include <stdbool.h>
#include "../utils/mem.h"

static seq_t *A219608_heap = NULL;
static size_t A219608_hsize = 0, A219608_hcap = 0;

static void A219608_push(seq_t val) {
    if (A219608_heap == NULL) {
        A219608_hcap = 16;
        A219608_heap = mem_new(seq_t, A219608_hcap);
    }
    if (A219608_hsize == A219608_hcap) {
        A219608_hcap <<= 1;
        A219608_heap = mem_resize(seq_t, A219608_heap, A219608_hcap);
    }
    size_t i = A219608_hsize++;
    A219608_heap[i] = val;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (A219608_heap[p] <= A219608_heap[i]) break;
        seq_t t = A219608_heap[p]; A219608_heap[p] = A219608_heap[i]; A219608_heap[i] = t;
        i = p;
    }
}

static seq_t A219608_pop(void) {
    seq_t ret = A219608_heap[0];
    A219608_hsize--;
    if (A219608_hsize > 0) {
        A219608_heap[0] = A219608_heap[A219608_hsize];
        size_t i = 0;
        while (1) {
            size_t l = i * 2 + 1, r = l + 1, s = i;
            if (l < A219608_hsize && A219608_heap[l] < A219608_heap[s]) s = l;
            if (r < A219608_hsize && A219608_heap[r] < A219608_heap[s]) s = r;
            if (s == i) break;
            seq_t t = A219608_heap[i]; A219608_heap[i] = A219608_heap[s]; A219608_heap[s] = t;
            i = s;
        }
    }
    return ret;
}

static seq_t *A219608_arr = NULL;
static size_t A219608_len = 0, A219608_cap = 0;

static void A219608_ensure(size_t n) {
    if (A219608_arr == NULL) {
        A219608_cap = 16;
        A219608_arr = mem_new(seq_t, A219608_cap);
        A219608_push((seq_t)0);
    }
    while (A219608_len <= n) {
        seq_t x = A219608_pop();
        if (A219608_len == A219608_cap) {
            A219608_cap <<= 1;
            A219608_arr = mem_resize(seq_t, A219608_arr, A219608_cap);
        }
        A219608_arr[A219608_len++] = x;
        A219608_push(x * (seq_t)2 + (seq_t)1);
        if (x != (seq_t)0) A219608_push(x * (seq_t)4);
    }
}

seq_t a(idx_t n) {
    size_t k = (size_t)(n - 1);
    A219608_ensure(k);
    return A219608_arr[k] * (seq_t)2 + (seq_t)1;
}
